arguments.command:
cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill
for b in rachel monica phoebe joey chandler ross; do
  echo "===== friend/$b =====";
  git log --format='%H %ci %s' origin/friend/$b -10;
done

cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill
for b in rachel monica phoebe joey chandler ross; do
  n=$(git log --format='%B' origin/friend/$b | grep -c 'Episode: S06/E16');
  echo "$b: $n";
done

cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill
git fetch origin --prune 2>&1 | tail
for b in rachel monica phoebe joey chandler ross; do
  echo "=== $b latest ===";
  git log -1 --format='%H %ci %s' origin/friend/$b;
done

for d in $(find / -maxdepth 5 -name .git -type d 2>/dev/null); do
  repo=$(dirname "$d");
  br=$(git -C "$repo" branch --show-current 2>/dev/null);
  if [ "$br" = "friends-3" ]; then echo "FOUND: $repo -> $br"; fi;
done
